use std::{fs,path::Path,io::Read,collections::BTreeSet};use serde_json::{json,Value};use sha2::{Digest,Sha256};
const R:&str="/home/ubuntu/src/zopro-perf-work/c7a-scale-profile245";const OLD:&str="/home/ubuntu/src/zopro-perf-work/full-c7a244";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn save(p:impl AsRef<Path>,v:Value){assert!(!p.as_ref().exists());fs::write(p,serde_json::to_vec_pretty(&v).unwrap()).unwrap();}
fn main(){let r=Path::new(R);let b=r.join("bundle");let old=Path::new(OLD);let cfgold=read(old.join("bundle/config/config.json"));let mut cfg=cfgold.clone();let mut cases=serde_json::Map::new();
let review=read(old.join("host-remote/review.json"));assert_eq!(review["passed"],true);assert_eq!(review["host_reverified_exports"],1640);let m=read(old.join("production-manifest.json"));for(p,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());}save(r.join("production-manifest.json"),m);
for shape in["1x2","merge-54x1"]{let c=cfgold["cases"][shape].clone();for(f,h)in[("image","image_sha256"),("request","request_sha256")]{let p=c[f].as_str().unwrap();assert_eq!(hash(old.join("bundle").join(p)),c[h].as_str().unwrap());fs::hard_link(old.join("bundle").join(p),b.join(p)).unwrap();}if shape=="1x2"{let k=c["aeglos_key"].as_str().unwrap();assert_eq!(hash(old.join("bundle").join(k)),c["aeglos_key_sha256"].as_str().unwrap());fs::hard_link(old.join("bundle").join(k),b.join(k)).unwrap();}cases.insert(shape.into(),c);}
cfg["cases"]=json!(cases);cfg["seed_count"]=json!(64133);let seed=old.join("host-remote/proof-sha256.json");assert_eq!(hash(&seed),"4ebd9384d39f83322d132500dc2abc2440992baff22d308509d1ccc326c8d240");let ledger:BTreeSet<String>=serde_json::from_value(read(&seed)).unwrap();assert_eq!(ledger.len(),64133);fs::copy(seed,b.join("config/seed.json")).unwrap();save(b.join("config/config.json"),cfg);
for p in["bin/sdk","bin/aeglos","bin/verify","bin/xtask","lib/libstdc++.so.6"]{fs::copy(old.join("bundle").join(p),b.join(p)).unwrap();}for n in["sdk","aeglos"]{assert_eq!(hash(b.join("bin").join(n)),cfgold[format!("{n}_sha256")].as_str().unwrap());}
for n in["runner","independent"]{fs::copy(r.join(n),b.join("bin").join(n)).unwrap();}
for n in["protocol.md","runner.rs","independent.rs","setup.rs"]{fs::copy(r.join(n),b.join("config").join(n)).unwrap();}
save(r.join("qualification-inheritance.json"),json!({"passed":true,"scope":"Reuse1640 verified244 exports by exactSDK/image/request/key/source188identity; no freshlocalSDKcalls","host_review_sha256":hash(old.join("host-remote/review.json")),"current_source_files":188,"cases":["1x2","merge-54x1"],"seed_count":64133}));
println!("Prepared exactcurrent+Aeglos,2matchedfixtures,188sources; inheritedfunctionalqualification; zero newproofs.");}
